UPDATE "record_types" SET "name" = 'review', "description" = 'One ingested review (written by reviews_ingest)', "fields" = '[{"name": "platform", "type": "text", "description": "Review platform"}, {"name": "text", "type": "long_text", "description": "Review text"}, {"name": "rating", "type": "number", "description": "Star rating as given"}, {"name": "rating_scale", "type": "number", "description": "Rating scale, usually 5"}, {"name": "title", "type": "text", "description": "Review title"}, {"name": "date", "type": "date", "description": "Review date"}, {"name": "product", "type": "text", "description": "Reviewed product"}, {"name": "verified_buyer", "type": "bool", "description": "Verified buyer"}, {"name": "url", "type": "url", "description": "Review URL"}, {"name": "language", "type": "text", "description": "ISO language code"}, {"name": "helpful_count", "type": "number", "description": "Helpful votes"}, {"name": "reply_text", "type": "long_text", "description": "Merchant reply"}]'::jsonb, "natural_key" = '{platform,text,date}' WHERE "name" = 'review_excerpt';
--> statement-breakpoint
UPDATE "record_types" SET "fields" = (SELECT COALESCE(jsonb_agg(e - 'required'), '[]'::jsonb) FROM jsonb_array_elements("fields") AS e);
